INSERT INTO public.career_paths (
  domain, title, slug, description, overview,
  salary_entry, salary_mid, salary_senior,
  perks, impact, exposure, eligibility,
  skills_needed, upsc_skill_mapping, difficulty_rating, growth_rate,
  courses, certifications, portfolio_projects, launchpad_weeks,
