  linkedin_groups, professional_associations, is_active
) VALUES

-- 1. Regulatory Affairs Specialist
(
  'Policy, Governance & Public Affairs',
  'Regulatory Affairs Specialist',
  'regulatory-affairs-specialist',
  'Navigate complex regulatory frameworks for pharma, fintech, or telecom companies.',
  'Regulatory Affairs Specialists help companies comply with government regulations. Ex-UPSC aspirants with policy knowledge are highly valued in pharma, fintech, and telecom sectors where navigating regulatory frameworks is critical. You act as a bridge between government bodies and corporates.',
  '₹8 LPA', '₹18 LPA', '₹35 LPA',
  ARRAY['Flexible hours in senior roles', 'Exposure to government functioning', 'Industry conferences', 'Performance bonuses'],
  'Ensure products and services reach citizens safely and legally. Your work directly shapes how regulations protect public health and commerce.',
  'Regular interaction with CDSCO, TRAI, SEBI, and MoHFW. Represent companies at regulatory hearings.',
  'Graduate in Science, Law, or Commerce; LLB or MBA preferred',
  ARRAY['Policy analysis', 'Regulatory writing', 'Stakeholder management', 'Compliance auditing', 'Government relations', 'Legal drafting'],
  'High overlap with GS Paper 2 (Governance, Polity), Law optional, and Public Administration optional. Overlap Score: 85%',
  3, 'High',
  '[{"title": "Regulatory Affairs Fundamentals", "provider": "RAPS", "url": "https://www.raps.org/learning/courses/regulatory-fundamentals", "free": false}, {"title": "Compliance & Regulatory Management", "provider": "Coursera (Duke)", "url": "https://www.coursera.org/specializations/compliance", "free": false}]'::jsonb,
  ARRAY['RAC (Regulatory Affairs Certification) by RAPS', 'PG Diploma in Regulatory Affairs (NIPER)'],
  ARRAY['Prepare a mock CDSCO drug license application dossier', 'Write a regulatory risk assessment for a hypothetical fintech product', 'Analyze a recent SEBI enforcement order and summarize compliance gaps'],
  '[{"week": 1, "focus": "Sector selection", "tasks": ["Choose pharma/fintech/telecom based on your optional subject", "Read key regulatory acts (Drugs Act, FSSAI, TRAI)", "Follow MoHFW, SEBI, TRAI circulars"]}, {"week": 2, "focus": "Regulatory writing", "tasks": ["Draft a mock compliance report", "Read 5 actual regulatory submission documents", "Learn CTD dossier format"]}, {"week": 3, "focus": "Networking", "tasks": ["Connect with RA professionals on LinkedIn", "Join RAPS India chapter", "Attend a FICCI Health webinar"]}, {"week": 4, "focus": "Application", "tasks": ["Apply to pharma/fintech startups for RA associate roles", "Prepare case study: how to obtain a drug license in India", "Apply to RAPS Regulatory Foundations Certificate"]}]'::jsonb,
  '₹5,000–₹50,000 (certifications)',
  'Apply via LinkedIn Jobs, Naukri, and IIMJobs. Target Sun Pharma, Dr. Reddy''s, Cipla, Razorpay, Airtel.',
  '[{"title": "Regulatory Affairs India - CDSCO Overview", "channel": "Pharma Careers", "url": "https://youtube.com"}, {"title": "How to Break into Regulatory Affairs", "channel": "RA Careers", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Compliance Advantage", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Regulatory Affairs Professionals India", "url": "https://linkedin.com"}, {"name": "FSSAI Regulatory Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['RAPS (Regulatory Affairs Professionals Society)', 'FSSAI India'],
  TRUE
),

-- 2. Judiciary Preparation (PCS-J)
(
  'Law & Legal Services',
  'Judiciary Preparation (PCS-J)',
  'pcs-j-judiciary',
  'Transition your UPSC preparation to crack state judicial services exams.',
  'Provincial Civil Services (Judicial) exams are a natural pivot for UPSC aspirants who studied law. The preparation overlap is significant — polity, law, and essay writing all transfer directly. PCS-J leads to becoming a Civil Judge / Munsiff, with a structured promotion ladder to District Judge and High Court.',
  '₹7 LPA', '₹14 LPA', '₹22 LPA',
  ARRAY['Government job security', 'Housing & transport allowance', 'Pension', 'Judicial discretion and authority'],
  'Deliver justice to thousands of citizens at the grassroots level. Reduce pendency in India''s overburdened courts.',
  'Regular court proceedings, interaction with lawyers, district administration, and High Court supervision.',
  'LLB mandatory; LLM advantageous for academic track',
  ARRAY['Constitutional law', 'Civil Procedure Code', 'Criminal Procedure Code', 'Evidence Act', 'Legal drafting', 'Judgment writing'],
  'Direct overlap with Law optional, GS Paper 2 (Polity, Governance), and Essay. Overlap Score: 90%',
  4, 'Stable',
  '[{"title": "PCS-J Complete Course", "provider": "Judiciary Gold", "url": "https://www.judiciarygold.com", "free": false}, {"title": "CPC & CrPC for Judiciary", "provider": "Law Sikho", "url": "https://lawsikho.com", "free": false}]'::jsonb,
  ARRAY['State PCS-J (varies by state)', 'LLM (optional, for academic track)'],
  ARRAY['Write 5 model civil judgments on common disputes', 'Prepare a case brief for a landmark Supreme Court case', 'Draft a written statement for a sample civil suit'],
  '[{"week": 1, "focus": "Gap analysis", "tasks": ["Compare your state PCS-J syllabus with UPSC GS", "Identify law papers not yet studied (CPC, CrPC, Evidence Act)", "Get bare acts for CPC, CrPC, IPC, Evidence Act, TP Act"]}, {"week": 2, "focus": "Core law subjects", "tasks": ["Start CPC — jurisdiction, pleadings, written statement", "Practice judgment writing with model answers", "Study recent High Court judgments from your state"]}, {"week": 3, "focus": "Mock tests", "tasks": ["Take 2 full-length PCS-J prelim mocks", "Join an online PCS-J test series", "Revise constitutional law (strong from UPSC prep)"]}, {"week": 4, "focus": "Mains prep", "tasks": ["Write 3 practice judgments", "Solve previous year mains papers", "Connect with PCS-J qualifiers on LinkedIn"]}]'::jsonb,
  '₹10,000–₹30,000 (coaching & test series)',
  'Register via State Public Service Commission websites. Check eligibility (LLB + age limit) carefully per state.',
  '[{"title": "PCS-J Preparation Strategy for UPSC Aspirants", "channel": "Judiciary Gold", "url": "https://youtube.com/judiciaryprep"}, {"title": "Judgment Writing Masterclass", "channel": "Law Tutor India", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Legal Ladder", "platform": "Spotify", "url": "https://spotify.com"}, {"title": "Bar & Bench Podcast", "platform": "Apple Podcasts", "url": "https://podcasts.apple.com"}]'::jsonb,
  '[{"name": "PCS-J Aspirants India", "url": "https://t.me"}, {"name": "Judiciary Exam Prep", "url": "https://facebook.com"}]'::jsonb,
  ARRAY['State Public Service Commission', 'Judiciary Gold (coaching)'],
  TRUE
),

-- 3. ADR Specialist
(
  'Law & Legal Services',
  'Alternative Dispute Resolution (ADR) Specialist',
  'adr-specialist',
  'Resolve high-stakes disputes as a mediator or arbitrator — without the courtroom.',
  'ADR is booming in India as courts decongest. Mediators, arbitrators, and conciliators are in high demand in commercial disputes, family law, labour, and international trade. UPSC aspirants bring strong analytical thinking, neutrality, and policy awareness — ideal traits for ADR.',
  '₹10 LPA', '₹22 LPA', '₹50 LPA',
  ARRAY['High autonomy', 'Flexible/remote work', 'International arbitration opportunities', 'Prestigious empanelments'],
  'Reduce judicial burden while delivering faster, confidential justice to parties in dispute.',
  'Work with top law firms, corporates, and international institutions like ICC, DIAC, MCIA.',
  'LLB preferred; graduates with ADR certification also eligible',
  ARRAY['Negotiation', 'Active listening', 'Legal drafting', 'Arbitration law', 'Conflict resolution', 'Emotional intelligence'],
  'Overlap with Law optional (Arbitration & Conciliation Act), GS Paper 2 (Dispute resolution), and Essay writing skills. Overlap Score: 75%',
  3, 'High',
  '[{"title": "Mediation and Conflict Resolution", "provider": "Coursera (UC Irvine)", "url": "https://www.coursera.org/learn/mediation", "free": false}, {"title": "Arbitration Law in India", "provider": "Law Sikho", "url": "https://lawsikho.com/course/certificate-course-arbitration-law-practice", "free": false}, {"title": "Harvard Negotiation Essentials", "provider": "edX (Harvard)", "url": "https://www.edx.org/course/negotiation-mastery", "free": false}]'::jsonb,
  ARRAY['CIArb (Chartered Institute of Arbitrators) Membership', 'ICA Mediation Certification', 'ICADR Mediator Certification'],
  ARRAY['Write a mock arbitration award for a hypothetical commercial dispute', 'Draft a mediation settlement agreement', 'Comparative note on DIAC vs ICC arbitration rules'],
  '[{"week": 1, "focus": "ADR landscape", "tasks": ["Read the Arbitration and Conciliation Act 1996 (amended 2021)", "Study Mediation Bill 2023", "Watch 3 recorded mock mediations on YouTube"]}, {"week": 2, "focus": "Training enrollment", "tasks": ["Enroll in ICA or ICADR mediation certification (40-hour course)", "Practice role-play mediation with a partner", "Study Harvard Negotiation Project materials (free online)"]}, {"week": 3, "focus": "Institution empanelment", "tasks": ["Apply to DIAC, MCIA, or Delhi HC Mediation Centre", "Connect with CIArb India chapter", "Build ADR profile on LinkedIn"]}, {"week": 4, "focus": "Practice cases", "tasks": ["Volunteer for community mediation under a legal aid authority", "Write a case note on a recent Indian arbitration award", "Apply to law firms for in-house ADR roles"]}]'::jsonb,
  '₹15,000–₹80,000 (CIArb/ICA certification)',
  'Apply via IIMJobs, LinkedIn. Approach Trilegal, AZB & Partners, Cyril Amarchand for in-house ADR roles.',
  '[{"title": "Introduction to Arbitration in India", "channel": "Arbitration India", "url": "https://youtube.com"}, {"title": "Mediation Techniques for Beginners", "channel": "ADR Skills", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "Dispute Resolution India", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "ADR Practitioners India", "url": "https://linkedin.com"}, {"name": "CIArb India Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['CIArb India', 'Indian Council of Arbitration (ICA)', 'ICADR'],
  TRUE
),

-- 4. School / College Teacher
(
  'Education & Training',
  'Teacher / Lecturer (School & College)',
  'school-college-teacher',
  'Shape future generations — in classrooms from elite schools to government colleges.',
  'Teaching is one of the most respected transitions for UPSC aspirants. Deep subject expertise in history, polity, economics, or geography translates directly to school/college teaching. From elite private schools (20+ LPA) to government college lectureships via NET/SET, the path is well-defined and deeply meaningful.',
  '₹5 LPA', '₹14 LPA', '₹25 LPA',
  ARRAY['Summer vacations', 'Government pension (college)', 'Job security', 'Social respect and impact'],
  'Directly shape the intellectual development of India''s next generation. Inspire students who may go on to become the change-makers of tomorrow.',
  'Interact with students, parents, academic boards, and researchers. Build institutional knowledge over decades.',
  'Graduate + B.Ed for schools; Post-Graduate + NET/SET for colleges',
  ARRAY['Deep subject knowledge', 'Communication', 'Curriculum design', 'Pedagogy', 'Research writing', 'Classroom management'],
  'Direct overlap with any UPSC optional subject. GS depth useful for interdisciplinary teaching. Overlap Score: 80%',
  2, 'Stable',
  '[{"title": "B.Ed Distance Program", "provider": "IGNOU", "url": "https://www.ignou.ac.in/bed", "free": false}, {"title": "UGC-NET Preparation", "provider": "Unacademy", "url": "https://unacademy.com/goal/ugc-net", "free": false}, {"title": "Effective Teaching in Higher Education", "provider": "Coursera (Berkeley)", "url": "https://www.coursera.org/learn/effective-teaching", "free": false}]'::jsonb,
  ARRAY['B.Ed (Bachelor of Education)', 'UGC-NET / State SET', 'CTET (for central govt schools)'],
  ARRAY['Design a 5-lesson curriculum module for Class 12 Political Science', 'Create an educational YouTube video on a UPSC GS topic', 'Write a research paper draft for a UGC journal'],
  '[{"week": 1, "focus": "Track selection", "tasks": ["Decide: school (B.Ed route) vs college (NET route)", "Research IGNOU distance B.Ed program", "Check UGC-NET syllabus for your optional subject"]}, {"week": 2, "focus": "Demo classes", "tasks": ["Record a 20-minute demo class on a topic from your optional", "Upload to YouTube as unlisted for feedback", "Visit 3 nearby private schools to inquire about roles"]}, {"week": 3, "focus": "NET/SET preparation", "tasks": ["Solve 5 years of UGC-NET previous papers", "Join an online NET coaching group on Telegram", "Study Paper 1 (teaching aptitude + research methodology)"]}, {"week": 4, "focus": "Applications", "tasks": ["Apply to 5 private schools with your demo video link", "Register for the next UGC-NET exam cycle", "Connect with NET-qualified teachers on LinkedIn"]}]'::jsonb,
  '₹50,000–₹2,00,000 (B.Ed or coaching)',
  'Apply to private schools directly. For government colleges, clear UGC-NET/SET, then apply via NTA or state PSC portals.',
  '[{"title": "How to Become a Lecturer After UPSC", "channel": "Education Careers India", "url": "https://youtube.com"}, {"title": "UGC NET Study Strategy", "channel": "NET Prep Hub", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Educator Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "UGC-NET Aspirants India", "url": "https://t.me"}, {"name": "Teachers of India", "url": "https://facebook.com"}]'::jsonb,
  ARRAY['UGC India', 'NCTE (National Council for Teacher Education)'],
  TRUE
),

-- 5. Curriculum Designer
(
  'Education & Training',
  'Curriculum Designer / Instructional Designer',
  'curriculum-designer',
  'Design learning experiences that actually work — for schools, EdTech, or corporates.',
  'Curriculum designers shape what and how people learn. Ex-UPSC aspirants bring deep subject expertise, structured thinking, and an understanding of exam-oriented education — making them naturals for designing courses for EdTech platforms, schools, or corporate L&D teams.',
  '₹8 LPA', '₹16 LPA', '₹30 LPA',
  ARRAY['Remote-friendly', 'Creative work', 'High demand from EdTech boom', 'No fixed location required'],
  'Shape how millions of Indian learners access quality education, particularly via EdTech platforms serving tier-2 and tier-3 cities.',
  'Work with content creators, product managers, engineers, and subject matter experts at top EdTech companies.',
  'Graduate in any field; education/teaching background preferred',
  ARRAY['Instructional design', 'Learning management systems', 'Content writing', 'Assessment design', 'Storyboarding', 'Bloom''s Taxonomy', 'ADDIE model'],
  'UPSC optional subject depth is directly applicable. Writing skills from Mains. Analytical structuring from GS preparation. Overlap Score: 75%',
  2, 'High',
  '[{"title": "Instructional Design Fundamentals", "provider": "Coursera (UC San Diego)", "url": "https://www.coursera.org/learn/instructional-design-foundations", "free": false}, {"title": "Articulate 360 Free Trial", "provider": "Articulate", "url": "https://articulate.com/360/trial", "free": true}]'::jsonb,
  ARRAY['ATD Instructional Design Certificate', 'Google Certificate in Instructional Design', 'Articulate Storyline Certification'],
  ARRAY['Design a complete 4-week online course with syllabus, quizzes, and activities', 'Create a learning outcomes document for a Class 10 history unit', 'Audit an existing EdTech course and write a redesign proposal'],
  '[{"week": 1, "focus": "ID fundamentals", "tasks": ["Study ADDIE and Bloom''s Taxonomy", "Analyze the structure of 3 popular Coursera courses", "Read ''The Art of Explanation'' by Lee LeFever"]}, {"week": 2, "focus": "Portfolio course", "tasks": ["Design a mini 5-module course on a UPSC topic", "Use Canva or Google Slides for storyboards", "Write clear learning objectives for each module"]}, {"week": 3, "focus": "Tools", "tasks": ["Learn Articulate Rise or Moodle (free trials)", "Build one interactive lesson with quiz", "Study Khan Academy content structure"]}, {"week": 4, "focus": "Apply", "tasks": ["Upload portfolio to personal website or Google Drive", "Apply to BYJU''S, Unacademy, Scaler, upGrad", "Connect with instructional designers on LinkedIn"]}]'::jsonb,
  '₹0–₹20,000 (mostly free tools available)',
  'Apply via LinkedIn Jobs, IIMJobs, and AngelList India. Target BYJU''S, Unacademy, upGrad, Scaler, Khan Academy India.',
  '[{"title": "Instructional Design for Beginners", "channel": "Tim Slade", "url": "https://youtube.com/timslade"}, {"title": "EdTech India Career Guide", "channel": "EdTech Careers", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The ID Chat Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Instructional Design India", "url": "https://linkedin.com"}, {"name": "EdTech Professionals India", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['ATD (Association for Talent Development)', 'eLearning Guild India'],
  TRUE
),

-- 6. TV News Producer
(
  'Media, Journalism & Content',
  'TV News Producer / Researcher',
  'tv-news-producer',
  'Drive the stories behind the cameras — research, produce, and shape news narratives.',
  'TV news production requires exactly what UPSC prep builds: speed-reading, synthesis, understanding of governance and current affairs, and the ability to explain complexity in simple terms. News researchers and producers are the intellectual backbone of any newsroom.',
  '₹7 LPA', '₹15 LPA', '₹30 LPA',
  ARRAY['Fast-paced stimulating work', 'Access to newsmakers', 'On-the-ground reporting exposure', 'Press credentials'],
  'Shape public discourse and hold power accountable through quality journalism that serves millions of viewers.',
  'Work with reporters, anchors, guests, editors, and bureau chiefs across India and internationally.',
  'Graduate; PG Diploma in Journalism/Mass Communication preferred',
  ARRAY['Current affairs depth', 'Script writing', 'Fact-checking', 'Video editing basics', 'Editorial judgment', 'Speed and accuracy under pressure'],
  'Current affairs depth from UPSC preparation is a massive advantage. GS Paper 2 (Governance, IR) and Essay writing skills directly apply. Overlap Score: 85%',
  3, 'Moderate',
  '[{"title": "Introduction to Journalism", "provider": "Coursera (Northwestern)", "url": "https://www.coursera.org/learn/journalism", "free": false}, {"title": "Fact-Checking in the Digital Age", "provider": "edX (Duke)", "url": "https://www.edx.org", "free": true}]'::jsonb,
  ARRAY['PG Diploma in Journalism (IIMC)', 'Digital Media Certificate (Asian College of Journalism)'],
  ARRAY['Write and record a 2-minute news bulletin on a current topic', 'Produce a 10-minute YouTube news show episode', 'Publish 3 fact-check articles on any platform'],
  '[{"week": 1, "focus": "Media immersion", "tasks": ["Shadow a news show for 1 week", "Write 5 explainer briefs on current policy issues", "Read Nieman Lab for journalism insights"]}, {"week": 2, "focus": "Script craft", "tasks": ["Write scripts for 3 TV news segments (2 mins each)", "Study how NDTV/Rajya Sabha TV structure panels", "Learn basic video editing on CapCut or DaVinci Resolve"]}, {"week": 3, "focus": "Network building", "tasks": ["Apply for internship at The Wire, NDTV, News18", "Connect with bureau chiefs on LinkedIn", "Submit a story pitch to any digital news outlet"]}, {"week": 4, "focus": "Placement", "tasks": ["Build a clips portfolio with 5 published pieces", "Apply to news researcher/desk writer roles", "Consider PG Diploma in Broadcast Journalism (IIMC, AJK MCRC)"]}]'::jsonb,
  '₹50,000–₹1,50,000 (PG Diploma if pursued)',
  'Apply to NDTV, News18, India Today, Rajya Sabha TV directly. Send writing samples to editors on LinkedIn.',
  '[{"title": "How Indian TV News is Made", "channel": "The Newsroom India", "url": "https://youtube.com"}, {"title": "Journalism Career Guide India", "channel": "Media Careers", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Scroll Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Indian Journalists Association", "url": "https://linkedin.com"}, {"name": "Digital Journalism India", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['Press Club of India', 'Indian Journalists Union (IJU)'],
  TRUE
),

-- 7. Documentary Filmmaker
(
  'Media, Journalism & Content',
  'Documentary Filmmaker',
  'documentary-filmmaker',
  'Tell the stories that matter — using the power of film to document India and the world.',
  'Documentary filmmaking is a powerful intersection of journalism, storytelling, and advocacy. Ex-UPSC aspirants often have deeply researched perspectives on social issues, history, governance failures, and policy — making them compelling documentary storytellers. Streaming platforms have created massive demand.',
  '₹5 LPA', '₹15 LPA', '₹50 LPA',
  ARRAY['Creative freedom', 'Travel', 'Festival recognition', 'Social impact', 'OTT opportunities'],
  'Create films that shift public opinion on important issues — from tribal rights to climate change to electoral reform.',
  'Work with OTT platforms, NGOs, international media organizations, and attend film festivals globally.',
  'No fixed requirement; strong research background is a major advantage',
  ARRAY['Storytelling', 'Scriptwriting', 'Video editing', 'Field research', 'Interviewing', 'Visual composition', 'Grant writing'],
  'UPSC research skills, GS knowledge of India''s social issues, and Essay writing craft all transfer directly to documentary making. Overlap Score: 65%',
  4, 'High',
  '[{"title": "Filmmaking Fundamentals", "provider": "MasterClass (Ron Howard)", "url": "https://www.masterclass.com/classes/ron-howard-teaches-directing", "free": false}, {"title": "DaVinci Resolve Complete Course", "provider": "YouTube (Darren Mostyn)", "url": "https://youtube.com", "free": true}]'::jsonb,
  ARRAY['FTII Short Course in Documentary', 'PSBT Grant Recipient', 'IDFA Academy Fellowship'],
  ARRAY['Direct a 10-minute documentary on a social issue in your city', 'Write a full documentary treatment and pitch deck', 'Submit one documentary to a film festival'],
  '[{"week": 1, "focus": "Craft study", "tasks": ["Watch 10 acclaimed Indian documentaries (Writing With Fire, An Insignificant Man)", "Study three-act structure in non-fiction storytelling", "Read ''Documentary Storytelling'' by Sheila Curran Bernard"]}, {"week": 2, "focus": "Equipment & editing", "tasks": ["Learn basic filming on your smartphone", "Complete a free DaVinci Resolve editing course", "Shoot a 3-minute mini-doc about your locality"]}, {"week": 3, "focus": "First project", "tasks": ["Choose a subject you researched for UPSC", "Script a 10-minute documentary treatment", "Apply for a doc film workshop (SRFTI, FTII short courses)"]}, {"week": 4, "focus": "Distribution", "tasks": ["Submit mini-doc to IDFA Doc Lab or MIFF open submissions", "Upload to YouTube and Vimeo", "Apply to PSBT grant program"]}]'::jsonb,
  '₹10,000–₹1,00,000 (equipment + FTII courses)',
  'Apply to PSBT, NFDC grants. Approach Netflix India and Disney+ Hotstar open submissions. Start on YouTube.',
  '[{"title": "How to Make a Documentary Film", "channel": "Filmmaker IQ", "url": "https://youtube.com/filmmakeriq"}, {"title": "India Documentary Scene", "channel": "Film Companion", "url": "https://youtube.com/filmcompanion"}]'::jsonb,
  '[{"title": "The Documentary Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Documentary Filmmakers India", "url": "https://facebook.com"}, {"name": "FTII Alumni Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['FTII (Film and Television Institute of India)', 'PSBT (Public Service Broadcasting Trust)', 'NFDC India'],
  TRUE
),

-- 8. Public Sector Consultant
(
  'Management Consulting & Strategy',
  'Public Sector Consultant',
  'public-sector-consultant',
  'Use your governance expertise to advise government bodies as an external consultant.',
  'Public sector consulting sits at the intersection of policy, governance, and management. Firms like BCG, Deloitte, PwC, and EY have large government advisory practices. UPSC aspirants bring an edge no MBA can replicate: deep understanding of how government actually works, from Cabinet committees to district administration.',
  '₹12 LPA', '₹25 LPA', '₹60 LPA',
  ARRAY['High-impact projects', 'Exposure to senior government officials', 'Travel across India', 'Strong alumni networks'],
  'Drive large-scale government transformation — from digitizing services to redesigning welfare delivery.',
  'Present to Secretaries, Ministers, and State Chief Ministers. Work on projects that affect crores of citizens.',
  'Graduate; MBA/MPP from top institution preferred but not mandatory',
  ARRAY['Policy analysis', 'Stakeholder management', 'Presentation skills', 'Data analysis', 'Report writing', 'Project management', 'Excel/PowerPoint'],
  'Deep overlap with entire UPSC GS syllabus. Public Administration optional is directly applicable. Overlap Score: 90%',
  3, 'High',
  '[{"title": "Consulting Case Interview Prep", "provider": "Victor Cheng (free)", "url": "https://www.caseinterview.com", "free": true}, {"title": "McKinsey Problem Solving", "provider": "Coursera (McKinsey)", "url": "https://www.coursera.org/learn/mckinsey-problem-solving", "free": false}]'::jsonb,
  ARRAY['MBA from IIM/ISB (strong advantage)', 'PMP Certification', 'PRINCE2 Foundation'],
  ARRAY['Write a consulting proposal for a Smart City mission component', 'Build an Excel model for a government scheme budget analysis', 'Create a 20-slide transformation strategy for a state ministry'],
  '[{"week": 1, "focus": "Consulting toolkit", "tasks": ["Learn MECE thinking from Victor Cheng (free YouTube)", "Download and study a BCG or McKinsey public sector report", "Practice building a PowerPoint pyramid-principle presentation"]}, {"week": 2, "focus": "Domain specialization", "tasks": ["Pick a sector: smart cities, health, education, defence, agriculture", "Write a 1000-word policy brief on a current government initiative", "Read NITI Aayog reports and dissect their structure"]}, {"week": 3, "focus": "Applications", "tasks": ["Apply to EY, Deloitte, PwC, KPMG government advisory roles", "Target Primus Partners, i-government, CRISIL GR India", "Prepare case interviews with public sector scenarios"]}, {"week": 4, "focus": "Prep for interviews", "tasks": ["Practice 10 consulting case studies", "Prepare your UPSC-to-consulting story", "Get an MBA referral if possible"]}]'::jsonb,
  '₹0–₹5,00,000 (MBA optional but helpful)',
  'Apply via IIMJobs, LinkedIn. Target McKinsey, BCG, EY, Deloitte, Primus Partners, i-government.',
  '[{"title": "How to Get into Public Sector Consulting", "channel": "Management Consulted", "url": "https://youtube.com/managementconsulted"}, {"title": "India Public Policy Consulting", "channel": "Policy Circle", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Strategy Digest", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Consulting Professionals India", "url": "https://linkedin.com"}, {"name": "Public Policy India Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['MCA (Management Consultancies Association)', 'CII Government Affairs'],
  TRUE
),

-- 9. Financial Journalist / Analyst
(
  'Banking, Finance & Economics',
  'Financial Journalist / Analyst',
  'financial-journalist-analyst',
  'Explain markets, money, and policy to India — as a writer or analyst.',
  'Financial journalism blends economics knowledge with writing and is booming with India''s growing investor class. UPSC aspirants with economics optional have a strong foundation in macro, fiscal policy, monetary policy, and public finance — exactly what financial media and research firms need.',
  '₹8 LPA', '₹18 LPA', '₹45 LPA',
