-- 18. Rehabilitation Counselor
(
  'Psychology & Counseling',
  'Rehabilitation Counselor',
  'rehabilitation-counselor',
  'Help people rebuild their lives after trauma, disability, or addiction.',
  'Rehabilitation counselors support individuals facing physical disabilities, mental health challenges, addiction recovery, or trauma. India has a massive shortage of trained counselors. For UPSC aspirants drawn to public service and human welfare, this is a deeply fulfilling path that directly serves vulnerable populations.',
  '₹6 LPA', '₹14 LPA', '₹28 LPA',
  ARRAY['Deeply meaningful work', 'Societal impact', 'Government job opportunities (MSJE)', 'Growing demand post-pandemic'],
  'Help India''s most vulnerable populations — persons with disabilities, addiction survivors, and trauma victims — rebuild their lives with dignity.',
  'Work with NIMHANS, AIIMS, government disability centers, and leading NGOs. Engage with Ministry of Social Justice & Empowerment.',
  'Graduate; Master''s in Psychology/Social Work/Rehabilitation required; RCI registration needed',
  ARRAY['Empathy', 'Active listening', 'Case management', 'Disability law (RPWD Act 2016)', 'Report writing', 'Psychological assessment basics', 'Crisis intervention'],
  'Understanding of social issues from GS Paper 1 and social justice policies from GS Paper 2 are relevant. Sociology optional is directly applicable. Overlap Score: 50%',
  4, 'High',
  '[{"title": "Introduction to Clinical Psychology", "provider": "Coursera (Yale)", "url": "https://www.coursera.org/learn/clinical-psychology", "free": false}, {"title": "Mental Health First Aid India", "provider": "iCall / TISS", "url": "https://icallhelpline.org", "free": true}]'::jsonb,
  ARRAY['RCI Registration (Rehabilitation Council of India)', 'M.Sc. in Clinical Psychology / MSW', 'Mental Health First Aid Certification'],
  ARRAY['Write a rehabilitation plan for a hypothetical client with acquired disability', 'Complete Mental Health First Aid certification and write a reflection', 'Design a community awareness program for disability rights in a district'],
  '[{"week": 1, "focus": "Foundation", "tasks": ["Read the Rights of Persons with Disabilities Act 2016", "Explore RCI (Rehabilitation Council of India) registration requirements", "Read ''Man''s Search for Meaning'' by Viktor Frankl"]}, {"week": 2, "focus": "Education path", "tasks": ["Research M.A. Psychology / MSW programs at Delhi University, TISS, Jamia", "Explore IGNOU MA Psychology (distance) for working professionals", "Attend a virtual seminar from iCall (TISS) or Vandrevala Foundation"]}, {"week": 3, "focus": "Volunteering", "tasks": ["Volunteer at iCall helpline or an addiction recovery center", "Take a free crisis counseling training from iCall or AASRA", "Connect with rehabilitation counselors at NIMHANS or AIIMS"]}, {"week": 4, "focus": "Career plan", "tasks": ["Apply to government rehabilitation centers under MSJE", "Apply to Vandrevala Foundation, iCall, Sangath for paid roles", "Register for RCI-approved training if you have a psychology background"]}]'::jsonb,
  '₹1,00,000–₹3,00,000 (MA Psychology or MSW program)',
  'Apply via LinkedIn Jobs, Naukri to Vandrevala Foundation, iCall TISS, Sangath, Asha for Education, Government DDRC Centers.',
  '[{"title": "Career in Counseling Psychology India", "channel": "Psychology India", "url": "https://youtube.com"}, {"title": "Disability Rights India", "channel": "NCPEDP", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Mind Space", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Mental Health Professionals India", "url": "https://linkedin.com"}, {"name": "RCI India Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['RCI (Rehabilitation Council of India)', 'NIMHANS', 'Vandrevala Foundation'],
  TRUE
),

-- 19. Satirical Content Creator / Stand-up Comedian
(
  'Entrepreneurship & Freelancing',
  'Satirical Content Creator / Stand-up Comedian',
  'satirical-content-creator',
  'Make India laugh at itself — and build a career from political satire and social commentary.',
  'India''s stand-up comedy and political satire scene has exploded, and its best voices combine wit with deep knowledge of policy, history, and society — exactly what UPSC aspirants have. From Netflix specials to YouTube channels with millions of followers, the medium has become mainstream and commercially viable.',
  '₹3 LPA', '₹15 LPA', '₹80 LPA',
  ARRAY['Creative freedom', 'No fixed office hours', 'Grow a devoted fan base', 'Netflix/OTT specials possible'],
  'Use humor to hold power accountable and help India process its complex political reality — a form of public service in its own right.',
  'Perform at Canvas Laugh Club, The Comedy Store India, corporate events. Collaborate with Netflix, Amazon, OML Entertainment.',
  'No formal requirement; UPSC knowledge of politics, history, and society is a massive advantage',
  ARRAY['Writing', 'Public speaking', 'Timing', 'Cultural observation', 'Social media', 'Video editing', 'Resilience'],
  'Deep knowledge of Indian polity, history, society, and current affairs from UPSC preparation is the core competitive advantage. Overlap Score: 60%',
  5, 'High',
  '[{"title": "Stand-up Comedy Writing", "provider": "MasterClass (Steve Martin)", "url": "https://www.masterclass.com/classes/steve-martin-teaches-comedy", "free": false}, {"title": "YouTube Creator Academy", "provider": "YouTube (free)", "url": "https://creatoracademy.youtube.com", "free": true}]'::jsonb,
  ARRAY['No formal certifications — your audience size and specials ARE your credentials'],
  ARRAY['Write and perform a full 10-minute stand-up set on tape', 'Create a 10-episode satirical YouTube series on Indian politics', 'Pitch an original satirical show concept to an OTT platform'],
  '[{"week": 1, "focus": "Study the craft", "tasks": ["Watch every Kunal Kamra, Varun Grover, and Vir Das special", "Read ''Born Standing Up'' by Steve Martin", "Write a 5-minute set about your UPSC journey — find the humor"]}, {"week": 2, "focus": "First performance", "tasks": ["Find open mics in your city on Instagram (#openmicdelhi etc.)", "Sign up for your first open mic — 5 minutes only", "Record your set on phone and watch it back critically"]}, {"week": 3, "focus": "Content creation", "tasks": ["Start a YouTube Shorts / Instagram Reels series on political satire", "Post 3 satirical takes on current news events this week", "Study how Dhruv Rathee structures his YouTube scripts"]}, {"week": 4, "focus": "Community", "tasks": ["Join open mic community: Canvas Laugh Club, The Comedy Store India", "Connect with other comics on Instagram and collaborate", "Write and test 10 new jokes this week"]}]'::jsonb,
  '₹0–₹10,000 (basic recording equipment)',
  'Start at open mics in your city. Build a social media following. Approach Canvas Laugh Club, OML Entertainment for paid shows once you have material.',
  '[{"title": "Kunal Kamra: Honest Talk", "channel": "Kunal Kamra", "url": "https://youtube.com/kunalkamra"}, {"title": "How to Start Stand-up Comedy in India", "channel": "The Comedy Hub", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Comedy India Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "Indian Stand-up Comedy Network", "url": "https://facebook.com"}, {"name": "Comedy Writers India", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['Canvas Laugh Club', 'OML Entertainment', 'East India Comedy', 'Comedy Store India'],
  TRUE
),

-- 20. Academic Researcher (PhD Track)
(
  'Education & Training',
  'Academic Researcher (PhD Track)',
  'academic-researcher-phd',
  'Advance human knowledge — through rigorous research in the humanities and social sciences.',
  'For UPSC aspirants with a deep passion for their subject, a PhD is a natural next step. India''s UGC-funded research fellowships (JRF) pay well enough to live on, and the academic job market rewards those with UPSC-level depth of knowledge. International postdoc opportunities are also growing for Indian scholars.',
  '₹4 LPA', '₹14 LPA', '₹28 LPA',
  ARRAY['Intellectual freedom', 'Academic conferences', 'International collaborations', 'Government research funding'],
  'Expand the frontiers of knowledge in disciplines critical to India''s development — history, political science, economics, sociology, and more.',
  'Interact with global academics, attend international conferences, publish in top journals, advise government bodies.',
  'Master''s degree required; NET-JRF for funded PhD in India',
  ARRAY['Research methodology', 'Academic writing', 'Critical analysis', 'Literature review', 'Statistical analysis', 'Grant writing', 'Presenting research'],
  'UPSC optional subject depth is the core advantage. GS preparation builds broad social science foundation. Research aptitude from Mains answer writing. Overlap Score: 80%',
  4, 'Moderate',
  '[{"title": "Research Methods in Social Sciences", "provider": "NPTEL", "url": "https://nptel.ac.in", "free": true}, {"title": "Academic Writing in English", "provider": "Coursera (Duke)", "url": "https://www.coursera.org/specializations/academic-english", "free": false}]'::jsonb,
  ARRAY['UGC-NET with JRF', 'PhD Degree (mandatory)', 'GRE (for international programs)'],
  ARRAY['Write a 3000-word research proposal on an original thesis topic', 'Submit a paper to a UGC CARE-listed journal', 'Present at one academic seminar or conference'],
  '[{"week": 1, "focus": "Research gap identification", "tasks": ["Identify 3 potential research questions from your UPSC preparation", "Read 10 recent journal articles in your field using JSTOR/Google Scholar", "Study PhD programs at JNU, DU, Hyderabad University, and IITs"]}, {"week": 2, "focus": "JRF preparation", "tasks": ["Register for UGC-NET with JRF option", "Study UGC-NET research methodology paper (Paper 1) deeply", "Write a 1000-word research statement for your proposed PhD topic"]}, {"week": 3, "focus": "Applications", "tasks": ["Research PhD programs: JNU, Hyderabad University, TISS, Jamia, IITs", "Study Ashoka and Azim Premji University for liberal arts research", "Contact potential supervisors by email with your research statement"]}, {"week": 4, "focus": "Strengthen application", "tasks": ["Write an abstract for a paper you could submit to a journal", "Attend a virtual academic conference in your field", "Take GRE if planning US/UK PhD applications"]}]'::jsonb,
  '₹0 (JRF stipend covers living costs; ₹1,00,000+ for international applications)',
  'Apply to JNU, Hyderabad University, TISS, Delhi University, Ashoka University. For international programs, target Oxford, Cambridge, and US universities with funded PhD programs.',
  '[{"title": "PhD in India After UPSC", "channel": "Academic Career India", "url": "https://youtube.com"}, {"title": "Research Methodology Simplified", "channel": "Research Scholar India", "url": "https://youtube.com"}]'::jsonb,
  '[{"title": "The Research Lab India", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "PhD Scholars India", "url": "https://facebook.com"}, {"name": "JNU Research Network", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['UGC (University Grants Commission)', 'ICSSR (Indian Council of Social Science Research)'],
  TRUE
),

-- 21. UX Researcher
(
  'Data, Analytics & Tech-Adjacent',
  'UX Researcher',
  'ux-researcher',
  'Understand how humans interact with technology — and make products that actually work.',
  'UX Research is one of the most accessible tech careers for non-programmers. It''s fundamentally about understanding human behavior — through interviews, surveys, and observation. UPSC aspirants who studied sociology, anthropology, or public administration are naturally skilled UX researchers. India''s product companies are hiring aggressively.',
  '₹10 LPA', '₹22 LPA', '₹55 LPA',
  ARRAY['Remote-friendly', 'Work on products used by millions', 'High pay without coding', 'Creative analytical work'],
  'Ensure that India''s digital products actually work for ordinary citizens — including those in tier-2/3 cities and rural areas.',
  'Work with product managers, designers, and engineers at top tech companies. Present research to leadership.',
  'Graduate in any field; psychology/sociology background is an advantage',
  ARRAY['Qualitative research', 'Interviewing', 'Survey design', 'Synthesis and pattern recognition', 'Figma (basic)', 'Usability testing', 'Storytelling with data'],
  'Sociology and Anthropology optionals are directly applicable. Research methodology from UPSC preparation transfers well. Overlap Score: 65%',
  2, 'High',
  '[{"title": "Google UX Design Certificate", "provider": "Coursera (Google)", "url": "https://www.coursera.org/professional-certificates/google-ux-design", "free": false}, {"title": "UX Research Methods", "provider": "Interaction Design Foundation", "url": "https://www.interaction-design.org/courses/user-research", "free": false}]'::jsonb,
  ARRAY['Google UX Design Certificate', 'NNGroup UX Certification', 'IxDF UX Research Certification'],
  ARRAY['Conduct a full usability study on a government app (e.g., DigiLocker) and write a report', 'Create a UX research portfolio with 3 case studies hosted on Notion', 'Run a competitive analysis for a product in your chosen domain'],
  '[{"week": 1, "focus": "UXR basics", "tasks": ["Read ''The User Experience Team of One'' by Leah Buley", "Watch Nielsen Norman Group free YouTube videos on UX research methods", "Complete Google UX Design Certificate (free via Coursera with audit)"]}, {"week": 2, "focus": "Practice research", "tasks": ["Conduct 5 user interviews about a digital product you use (WhatsApp, Google Pay)", "Synthesize findings into an affinity diagram", "Write up a research report with key insights and recommendations"]}, {"week": 3, "focus": "Tools", "tasks": ["Learn Figma basics (free)", "Practice with Dovetail or Notion for research synthesis", "Create a simple usability test script and run it with 3 friends"]}, {"week": 4, "focus": "Apply", "tasks": ["Build a UXR portfolio with 2 case studies on Notion", "Apply to Flipkart, Swiggy, PhonePe, Razorpay, Zoho for UXR roles", "Apply to Google, Microsoft India — they hire researchers from humanities backgrounds"]}]'::jsonb,
  '₹5,000–₹30,000 (certifications)',
  'Apply via LinkedIn Jobs, AngelList India, IIMJobs. Target Flipkart, Swiggy, PhonePe, Razorpay, Zoho, Google India, Microsoft India.',
  '[{"title": "UX Research for Beginners", "channel": "AJ&Smart", "url": "https://youtube.com/ajsmart"}, {"title": "Breaking into UX from Non-Tech Background", "channel": "NNGroup", "url": "https://youtube.com/nngroup"}]'::jsonb,
  '[{"title": "UI Breakfast Podcast", "platform": "Spotify", "url": "https://spotify.com"}]'::jsonb,
  '[{"name": "UX Researchers India", "url": "https://linkedin.com"}, {"name": "UX India Community", "url": "https://linkedin.com"}]'::jsonb,
  ARRAY['IxDF (Interaction Design Foundation)', 'NNGroup India', 'UX India'],
  TRUE
)
